public int prime_Sum(int n) {
    // code here

    long sum=0;

    for(int i=1;i<=n;i++){
        int count=0;
        if(i<=1)continue;

        for(int j=1;j*j<=i;j++){
            if(i%j==0){
                count++;
                if((i/j)!=j){
                    count++;

                }
            }
        }
        if(count==2){
            sum=sum+i;
        }
    }

    return (int)sum;

}
